340				if !strings.Contains(msg, tc.want) || !strings.Contains(msg, "value must be a string") {
341					t.Fatalf("stderr=%q, want %s string-type error", msg, tc.want)
342				}
343				if strings.Contains(msg, "invalid JSON") {
