393			t.Fatalf("stdout must contain exactly one JSON object line: %q", out)
394		}
395		var got map[string]any
396		if err := json.Unmarshal(stdout.Bytes(), &got); err != nil {
397			t.Fatalf("stdout is not a single JSON object: %q (%v)", out, err)
398		}
399		if got["key"] != "feature-big" || got["value"] != true ||
400			got["reason"] != "rule" || got["ruleId"] != "r-big" {
401			t.Fatalf("unexpected payload: %v", got)
402		}
