func TestCLIEvaluateDuplicateFlagKeyAcrossSpellings(t *testing.T) {
	flag := func(keyJSON string, enabled bool) string {
		return `{"key":"` + keyJSON + `","enabled":` + map[bool]string{true: "true", false: "false"}[enabled] + `,"default":false,"rules":[]}`
	}
